kubectl get secret argocd-acr-pull-secret -n argocd -o json 2>&1 | python3 -c "
import json, sys, base64
s = json.load(sys.stdin)
print('=== argocd-acr-pull-secret ===')
for k, v in s.get('data', {}).items():
    try:
        decoded = base64.b64decode(v).decode('utf-8')
        # Redact anything that looks like a password/secret
        if any(x in k.lower() for x in ['password', 'secret', 'token', 'key']):
            print(f'{k}: <REDACTED len={len(decoded)}>')
        else:
            print(f'{k}: {decoded}')
    except Exception as e:
        print(f'{k}: <binary or decode error: {e}>')
"

